<script>
 import { tick } from 'svelte';
 import './disk-native.css';
 let { state: nativeBootCampAssistantState, windowId, profile, controller, execute, registerView } = $props();
 let root = $state(), scroller = $state(), feedback = $state(''), isoFileId = $state(''), capacityBytes = $state(0), confirmation = $state(false);
 let session = $derived(nativeBootCampAssistantState.sessions.find(row => row.windowId === windowId));
 let windows = $derived(profile.id.startsWith('windows'));
 let classic = $derived(/high-sierra|mojave/.test(profile.id));
 let files = $derived.by(() => { void nativeBootCampAssistantState; void session; return controller.getFiles(); });
 let volumes = $derived.by(() => { void nativeBootCampAssistantState; void session; return controller.getVolumes(); });
 let isoFiles = $derived(files.filter(file => file.kind !== 'folder' && /\.iso$/i.test(file.name)));
 let iso = $derived(files.find(file => file.id === session?.isoFileId));
 let volume = $derived(volumes.find(row => row.rootFileId === session?.volumeRootId) ?? volumes.find(row => row.internal && row.mounted));
 let maximum = $derived(Math.max(0, (volume?.capacityBytes ?? 0) - (volume?.usedBytes ?? 0)));
 const bytes = n => new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 }).format((n ?? 0) / 1e9) + ' GB';
 async function send(command, payload = {}) { try { const result = await execute(command, { windowId }, payload); feedback = result?.status === 'rejected' ? result.error?.message ?? 'Boot Camp could not proceed.' : ''; return result; } catch (error) { feedback = error.message; } }
 async function next() { if (session.stage === 'source') { const result = await send('bootcamp.iso', { fileId: isoFileId }); if (result?.status !== 'applied') return; } if (session.stage === 'select') { const result = await send('bootcamp.partition', { capacityBytes }); if (result?.status !== 'applied') return; } await send('bootcamp.next'); }
 async function start() { confirmation = false; await send('bootcamp.start', { confirm: true }); }
 $effect(() => { isoFileId = session?.isoFileId ?? ''; capacityBytes = session?.capacityBytes ?? 0; if (session?.stage !== 'ready') confirmation = false; });
 $effect(() => { if (confirmation) void tick().then(() => root?.querySelector('[data-bootcamp-control="confirm-cancel"]')?.focus()); });
 function sheetKeys(event) { if (event.key === 'Escape') { event.preventDefault(); confirmation = false; } if (event.key === 'Tab') { const controls = [...event.currentTarget.querySelectorAll('button')].filter(node => !node.disabled); if (event.shiftKey && event.target === controls[0]) { event.preventDefault(); controls.at(-1)?.focus(); } else if (!event.shiftKey && event.target === controls.at(-1)) { event.preventDefault(); controls[0]?.focus(); } } }
 $effect(() => {
  const original = root, originalScroller = scroller, originalSession = session; if (!original || !originalScroller || !originalSession) return;
  let retired = false;
  const available = () => !retired && root === original && scroller === originalScroller && original.isConnected && nativeBootCampAssistantState.sessions.find(row => row.windowId === windowId) === originalSession;
  const find = (attribute, id) => [...original.querySelectorAll(`[${attribute}]`)].find(node => node.getAttribute(attribute) === id && node.getClientRects().length && !node.disabled && !node.closest('[inert]'));
  const reject = () => ({ status: 'rejected', error: { code: 'stale_target', message: 'The original mounted Boot Camp Assistant view is unavailable.' } });
  const view = { available, describe: () => available() ? { windowId, controlIds: [...original.querySelectorAll('[data-bootcamp-control]')].map(node => node.dataset.bootcampControl), areaIds: ['content'] } : null,
   async focus(target, guard = () => true) { const controlId = typeof target === 'string' ? target : target.controlId, node = find('data-bootcamp-control', controlId); if (!available() || guard() !== true || !node) return reject(); node.focus(); await tick(); return available() && guard() === true && find('data-bootcamp-control', controlId) === node && node.ownerDocument.activeElement === node ? { status: 'applied', controlId } : reject(); },
   async scroll({ areaId = 'content', top = 0, left = 0 }, guard = () => true) { const node = find('data-bootcamp-area', areaId); if (!available() || guard() !== true || !node) return reject(); node.scrollTo({ top, left, behavior: 'instant' }); await tick(); return available() && guard() === true && find('data-bootcamp-area', areaId) === node ? { status: 'applied', areaId, top: node.scrollTop, left: node.scrollLeft } : reject(); }, destroy() { retired = true; } };
  const unregister = registerView(windowId, view); return () => { view.destroy(); if (typeof unregister === 'function') unregister(); };
 });
</script>

{#if session}
<section bind:this={root} class="disk-native disk-wizard bootcamp-wizard" class:disk-classic={classic} class:disk-windows={windows} aria-label={classic ? 'Boot Camp Assistant' : 'Boot Camp local equivalent'}>
 {#if windows}<p class="disk-disclosure">Functional local Boot Camp equivalent. Boot Camp is a Mac utility, not a Windows 11 application. No operating system is installed.</p>{:else if !classic}<p class="disk-disclosure">Boot Camp requires an Intel Mac and is absent on Apple silicon. This is an explicitly local partition-and-image equivalent, not a native Apple-silicon Boot Camp backport.{profile.id.includes('golden-gate') ? ' macOS 27 native appearance is unverified; nearest macOS 26-inspired styling.' : ''}</p>{/if}
 <main bind:this={scroller} class="disk-wizard-content" data-bootcamp-area="content" tabindex="0" inert={confirmation}>
  <div class="bootcamp-illustration" aria-hidden="true"><svg viewBox="0 0 150 100"><defs><linearGradient id={`boot-drive-${windowId}`} x2="0" y2="1"><stop stop-color="#f6f6f6"/><stop offset="1" stop-color="#b6b7ba"/></linearGradient></defs><path d="M35 12h80l15 66H20z" fill={`url(#boot-drive-${windowId})`} stroke="#808286"/><rect x="20" y="72" width="110" height="15" rx="4" fill="#b7b9bc" stroke="#808286"/><circle cx="117" cy="80" r="2" fill="#51aa47"/><path d="M75 24v43" stroke="#6b6d70" stroke-width="2"/><path d="M48 38h-9v15h9l-5 6H32V33h11z" fill="#81838b"/><path d="m88 33 14-2v13H88zm16-2 15-2v15h-15zM88 46h14v13l-14-2zm16 0h15v16l-15-3z" fill="#727982"/></svg></div>
  {#if session.stage === 'intro'}<h1>{classic ? 'Introduction' : 'Boot Camp · Local Equivalent'}</h1><p>Boot Camp Assistant helps you prepare a Windows partition on an Intel-era Mac.</p><p>In this scene, choose a real ISO document and allocate a local BOOTCAMP volume. The controller verifies the image and creates actual local Files metadata; it does not download drivers, restart this computer, or run a Windows installer.</p><p class="disk-local-note">The included “Virtual boot demo.iso” is a genuine x86 El Torito boot image for this local workflow, not a Windows installation disc.</p><div class="disk-wizard-callout">Back up your local files before allocating volume space.</div>
  {:else if session.stage === 'source'}<h1>Select an ISO Image</h1><p>Choose an ISO from the actual Files store. A filename alone is not proof of a valid boot image; the image is validated by the controller.</p><p class="disk-local-note">The included “Virtual boot demo.iso” contains an x86 boot demonstration, not Windows. Disk Utility’s ordinary ISO9660 exports are data images, not Windows installers.</p><label>ISO image<select data-bootcamp-control="iso" bind:value={isoFileId}><option value="">Choose ISO image…</option>{#each isoFiles as file}<option value={file.id}>{file.name}</option>{/each}</select></label>{#if !isoFiles.length}<p class="disk-warning">No ISO documents are available. Import a genuine bootable ISO in Files before continuing.</p>{/if}{#if isoFileId}<dl class="disk-properties"><dt>Original file ID</dt><dd>{isoFileId}</dd><dt>Revision</dt><dd>{files.find(file => file.id === isoFileId)?.revision ?? 'Unavailable'}</dd></dl>{/if}
  {:else if session.stage === 'select'}<h1>Create a Partition for Windows</h1><p>Drag the divider to choose the capacity of the new local BOOTCAMP volume.</p><div class="bootcamp-partition"><div><span class="disk-small-drive" aria-hidden="true"></span><strong>{volume?.name ?? 'No internal volume'}</strong><small>{bytes(Math.max(0, (volume?.capacityBytes ?? 0) - capacityBytes))}</small></div><div><span class="bootcamp-windows-mark" aria-hidden="true">⊞</span><strong>BOOTCAMP</strong><small>{bytes(capacityBytes)}</small></div></div><input class="bootcamp-divider" type="range" min="1" max={Math.max(1, maximum)} step="1" data-bootcamp-control="partition-slider" bind:value={capacityBytes} disabled={!volume || maximum < 1} aria-label="BOOTCAMP partition capacity in bytes"/><label>Windows partition capacity (bytes)<input type="number" min="1" max={maximum} step="1" data-bootcamp-control="partition-capacity" bind:value={capacityBytes}/></label><p>{bytes(maximum)} available on {volume?.name ?? 'the source volume'}. Existing files remain on the original volume.</p><p class="disk-local-note">This is local scene capacity accounting, not a resized host filesystem or bootable Windows installation.</p>
  {:else if session.stage === 'ready'}<h1>Ready to Create BOOTCAMP</h1><dl class="disk-properties"><dt>ISO image</dt><dd>{iso?.name ?? 'Original image unavailable'}</dd><dt>Original volume</dt><dd>{volume?.name ?? 'Unavailable'}</dd><dt>Windows capacity</dt><dd>{bytes(session.capacityBytes)}</dd></dl><p>Continue to confirm the local volume change. No firmware, startup disk, or host operating system will be modified.</p>
  {:else if session.stage === 'running'}<h1>Creating the Local Windows Volume</h1><progress max="100" value={session.progress} aria-label="Boot Camp volume progress"></progress><p>{session.progress}%</p><p>No host installer or driver download is running.</p>
  {:else if session.stage === 'complete'}<h1>BOOTCAMP Preparation Complete</h1><p>{session.message}</p><p>The actual local BOOTCAMP volume and image metadata are available in Files and Disk Utility. This does not represent an installed or bootable Windows operating system.</p>{/if}
  {#if feedback}<p class="disk-error" role="alert">{feedback}</p>{/if}<p class="disk-wizard-message" role="status">{session.stage !== 'complete' ? session.message : ''}</p>
 </main>
 <footer class="disk-wizard-footer" inert={confirmation}><span class="disk-step-indicator">{['intro','source','select','ready','running','complete'].indexOf(session.stage) + 1} of 6</span><button data-bootcamp-control="cancel" onclick={() => send('bootcamp.cancel')}>{session.stage === 'running' ? 'Cancel Operation' : 'Cancel'}</button><button data-bootcamp-control="back" disabled={session.stage === 'intro' || session.stage === 'running'} onclick={() => send('bootcamp.back')}>Go Back</button>{#if session.stage === 'ready'}<button class="disk-default" data-bootcamp-control="create" onclick={() => confirmation = true}>Create Volume…</button>{:else if session.stage !== 'running' && session.stage !== 'complete'}<button class="disk-default" data-bootcamp-control="continue" disabled={(session.stage === 'source' && !isoFileId) || (session.stage === 'select' && (!volume || capacityBytes < 1 || capacityBytes > maximum))} onclick={next}>Continue</button>{/if}</footer>
 {#if confirmation}<div class="disk-sheet-shade"><section class="disk-sheet" role="dialog" aria-modal="true" aria-label="Confirm BOOTCAMP partition" tabindex="-1" onkeydown={sheetKeys}><h2>Create a {bytes(session.capacityBytes)} BOOTCAMP volume?</h2><p>This allocates capacity from “{volume?.name}” and records the selected ISO “{iso?.name}” in the actual local Files store. Review the capacity before proceeding.</p><p>Host partitions and operating systems are not touched.</p><div class="disk-actions"><button data-bootcamp-control="confirm-cancel" onclick={() => confirmation = false}>Cancel</button><button class="disk-default" data-bootcamp-control="confirm-create" onclick={start}>Create BOOTCAMP Volume</button></div></section></div>{/if}
</section>
{/if}
